style.css:
@-moz-document domain("youtube.com") {
/* Set full-screen background image */
    html {
        background: url("https://i.postimg.cc/jjHcdGXT/profo.jpg") no-repeat center center fixed;
        background-size: cover !important;
    }

    /* Make main content area transparent */
    #page-manager, ytd-app {
        background: transparent !important;
    }

    /* Make sidebar transparent */
    #guide-content, #guide {
        background: transparent !important;
    }

    /* Make the header (top bar) transparent */
    #masthead-container {
        background: rgba(0, 0, 0, 0.3) !important; /* Optional: Semi-transparent */
    }

    /* Change video title color */
    ytd-video-primary-info-renderer h1.title {
        color: white !important;
    }

    /* Change video description color */
    #description {
        color: white !important;
    }

    /* Fix text color issues */
    ytd-guide-entry-renderer a,
    ytd-topbar-logo-renderer,
    ytd-mini-guide-entry-renderer {
        color: white !important;
    }

    /* Hide ads */
    .ytd-ad-slot-renderer, .ytp-ad-module {
        display: none !important;
    }
}
